import type { Batch, SkuRow } from './columns'

export type StockStatus = 'Short' | 'Reorder' | 'Healthy'

export interface SkuMetrics {
  onHand: number
  allocated: number
  /** On hand minus what's already promised to orders. */
  available: number
  /** Open order demand not yet covered by an allocation. */
  unallocated: number
  /** dailyDemand × leadTimeDays + safetyStock */
  reorderPoint: number
  /** Available stock net of unallocated demand — what reorders are judged on. */
  position: number
  daysOfCover: number
  /** Rounded up to whole case packs so the suggestion is actually orderable. */
  reorderQty: number
  status: StockStatus
}

export function isExpired(batch: Batch, today = new Date()) {
  return new Date(batch.expiresOn) < today
}

/**
 * Every derived number in the grid comes from here. Nothing computed is ever
 * stored on the row, so editing one input (a batch allocation, a lead time)
 * can't leave a stale total somewhere else — the next render recomputes all
 * of it from the raw values.
 */
export function deriveMetrics(row: SkuRow): SkuMetrics {
  const usable = row.batches.filter((b) => !isExpired(b))
  const onHand = usable.reduce((sum, b) => sum + b.onHand, 0)
  const allocated = row.batches.reduce((sum, b) => sum + b.allocated, 0)
  const available = onHand - allocated
  const unallocated = Math.max(0, row.orderedQty - allocated)
  const reorderPoint = row.dailyDemand * row.leadTimeDays + row.safetyStock
  const position = available - unallocated
  const daysOfCover =
    row.dailyDemand > 0 ? Math.max(0, position) / row.dailyDemand : Infinity
  const shortfall = Math.max(0, reorderPoint - position)
  const reorderQty = Math.ceil(shortfall / row.casePack) * row.casePack

  const status: StockStatus =
    unallocated > available
      ? 'Short'
      : position < reorderPoint
        ? 'Reorder'
        : 'Healthy'

  return {
    onHand,
    allocated,
    available,
    unallocated,
    reorderPoint,
    position,
    daysOfCover,
    reorderQty,
    status,
  }
}

/**
 * First-expired, first-out: fill the SKU's open order demand from the
 * batch that expires soonest, skipping expired stock entirely. Existing
 * allocations are replaced, not added to.
 */
export function allocateFefo(row: SkuRow): Batch[] {
  let remaining = row.orderedQty
  const order = [...row.batches]
    .filter((b) => !isExpired(b))
    .sort((a, b) => a.expiresOn.localeCompare(b.expiresOn))
    .map((b) => b.id)

  const allocations = new Map<string, number>()
  for (const id of order) {
    const batch = row.batches.find((b) => b.id === id)!
    const take = Math.min(batch.onHand, remaining)
    allocations.set(id, take)
    remaining -= take
  }

  return row.batches.map((b) => ({ ...b, allocated: allocations.get(b.id) ?? 0 }))
}

'use client'

import { useState } from 'react'
import { Input } from '#/components/ui/input'
import { cn } from '#/lib/utils.ts'

interface EditableNumberCellProps {
  value: number
  onCommit: (value: number) => void
  /** Return an error message to block the commit, or null to accept it. */
  validate?: (value: number) => string | null
  suffix?: string
  label: string
  disabled?: boolean
}

export function EditableNumberCell({
  value,
  onCommit,
  validate,
  suffix,
  label,
  disabled,
}: EditableNumberCellProps) {
  const [draft, setDraft] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  function commit() {
    if (draft === null) return
    const n = Number(draft)
    const message =
      draft.trim() === '' || !Number.isInteger(n) || n < 0
        ? 'Enter a whole number ≥ 0'
        : (validate?.(n) ?? null)

    // An invalid value keeps the input open so the user can fix it in place,
    // rather than silently snapping back to the old number.
    if (message) {
      setError(message)
      return
    }
    setDraft(null)
    setError(null)
    if (n !== value) onCommit(n)
  }

  function cancel() {
    setDraft(null)
    setError(null)
  }

  if (draft !== null) {
    return (
      <div className="w-24">
        <Input
          autoFocus
          type="number"
          inputMode="numeric"
          min={0}
          aria-label={label}
          aria-invalid={error ? true : undefined}
          value={draft}
          onChange={(e) => {
            setDraft(e.target.value)
            setError(null)
          }}
          onBlur={() => (error ? cancel() : commit())}
          onKeyDown={(e) => {
            if (e.key === 'Enter') commit()
            if (e.key === 'Escape') cancel()
          }}
          className="h-7 px-2 tabular-nums"
        />
        {error ? (
          <p role="alert" className="mt-1 text-xs text-destructive">
            {error}
          </p>
        ) : null}
      </div>
    )
  }

  return (
    <button
      type="button"
      disabled={disabled}
      aria-label={`Edit ${label}`}
      onClick={() => setDraft(String(value))}
      className={cn(
        '-mx-1.5 rounded border border-dashed border-transparent px-1.5 py-1 text-left tabular-nums',
        'hover:border-border hover:bg-muted focus-visible:border-ring focus-visible:outline-none',
        'disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-transparent disabled:hover:bg-transparent',
      )}
    >
      {value.toLocaleString()}
      {suffix ? <span className="text-muted-foreground"> {suffix}</span> : null}
    </button>
  )
}

'use client'

import type { ColumnDef, Table } from '@tanstack/react-table'
import { ChevronRight } from 'lucide-react'
import { Badge } from '#/components/ui/badge'
import { cn } from '#/lib/utils.ts'
import { EditableNumberCell } from './editable-cell'
import type { SkuMetrics, StockStatus } from './formulas'
import { deriveMetrics } from './formulas'

export type Batch = {
  id: string
  lot: string
  location: string
  /** ISO date (yyyy-mm-dd) */
  expiresOn: string
  onHand: number
  allocated: number
}

export type SkuRow = {
  sku: string
  name: string
  casePack: number
  /** Units on open orders waiting to be allocated from stock. */
  orderedQty: number
  dailyDemand: number
  leadTimeDays: number
  safetyStock: number
  batches: Batch[]
}

export type EditableSkuField = 'dailyDemand' | 'leadTimeDays' | 'safetyStock'

/**
 * Handed to the table through `meta` so static column definitions can write
 * back to state without closing over it — the columns array never has to be
 * rebuilt when data changes.
 */
export interface InventoryTableMeta {
  updateSku: (sku: string, field: EditableSkuField, value: number) => void
  updateBatch: (sku: string, batchId: string, allocated: number) => void
  autoAllocate: (sku: string) => void
}

export function getMeta(table: Table<SkuRow>) {
  return table.options.meta as InventoryTableMeta
}

const statusStyles: Record<StockStatus, string> = {
  Short: 'bg-destructive/15 text-destructive dark:bg-destructive/25 dark:text-red-300',
  Reorder: 'bg-amber-100 text-amber-800 dark:bg-amber-500/15 dark:text-amber-300',
  Healthy: 'bg-emerald-100 text-emerald-800 dark:bg-emerald-500/15 dark:text-emerald-300',
}

// Footers sum the same derived metrics the cells render, so a total can
// never disagree with the rows above it.
function sumFooter(table: Table<SkuRow>, pick: (m: SkuMetrics) => number) {
  const total = table
    .getRowModel()
    .rows.reduce((sum, r) => sum + pick(deriveMetrics(r.original)), 0)
  return <span className="tabular-nums">{total.toLocaleString()}</span>
}

const statusRank: Record<StockStatus, number> = { Short: 0, Reorder: 1, Healthy: 2 }

function editableColumn(
  field: EditableSkuField,
  header: string,
  suffix?: string,
): ColumnDef<SkuRow> {
  return {
    accessorKey: field,
    header,
    cell: ({ row, table }) => (
      <EditableNumberCell
        label={`${header} for ${row.original.sku}`}
        value={row.original[field]}
        suffix={suffix}
        validate={(n) => (field === 'leadTimeDays' && n === 0 ? 'Must be at least 1' : null)}
        onCommit={(n) => getMeta(table).updateSku(row.original.sku, field, n)}
      />
    ),
  }
}

export const columns: ColumnDef<SkuRow>[] = [
  {
    id: 'expander',
    header: () => <span className="sr-only">Batches</span>,
    enableSorting: false,
    cell: ({ row }) => (
      <button
        type="button"
        onClick={row.getToggleExpandedHandler()}
        aria-label={row.getIsExpanded() ? 'Hide batches' : 'Show batches'}
        aria-expanded={row.getIsExpanded()}
        className="flex size-6 items-center justify-center rounded text-muted-foreground hover:bg-muted hover:text-foreground"
      >
        <ChevronRight
          className={cn('size-3.5 transition-transform', row.getIsExpanded() && 'rotate-90')}
        />
      </button>
    ),
  },
  {
    accessorKey: 'sku',
    header: 'SKU',
    cell: ({ row }) => (
      <div className="min-w-40">
        <p className="font-medium">{row.original.name}</p>
        <p className="font-mono text-xs text-muted-foreground">
          {row.original.sku} · {row.original.batches.length}{' '}
          {row.original.batches.length === 1 ? 'batch' : 'batches'}
        </p>
      </div>
    ),
    footer: () => <span>Totals</span>,
  },
  {
    id: 'status',
    header: 'Status',
    accessorFn: (row) => statusRank[deriveMetrics(row).status],
    cell: ({ row }) => {
      const { status } = deriveMetrics(row.original)
      return (
        <Badge variant="outline" className={cn('border-transparent', statusStyles[status])}>
          {status}
        </Badge>
      )
    },
  },
  {
    id: 'available',
    header: 'Available',
    accessorFn: (row) => deriveMetrics(row).available,
    cell: ({ row }) => {
      const { available, onHand } = deriveMetrics(row.original)
      return (
        <div className="tabular-nums">
          <p>{available.toLocaleString()}</p>
          <p className="text-xs text-muted-foreground">of {onHand.toLocaleString()} on hand</p>
        </div>
      )
    },
    footer: ({ table }) => sumFooter(table, (m) => m.available),
  },
  {
    id: 'allocation',
    header: 'Allocated',
    accessorFn: (row) => {
      const { allocated } = deriveMetrics(row)
      return row.orderedQty ? allocated / row.orderedQty : 1
    },
    cell: ({ row }) => {
      const { allocated, unallocated } = deriveMetrics(row.original)
      const pct = row.original.orderedQty
        ? Math.min(100, (allocated / row.original.orderedQty) * 100)
        : 100
      return (
        <div className="w-32 space-y-1.5 tabular-nums">
          <p className="text-xs">
            {allocated.toLocaleString()} / {row.original.orderedQty.toLocaleString()}
            {unallocated > 0 ? (
              <span className="text-muted-foreground"> · {unallocated} open</span>
            ) : null}
          </p>
          <div className="h-1.5 overflow-hidden rounded-full bg-muted">
            <div
              className={cn('h-full rounded-full', unallocated > 0 ? 'bg-amber-500' : 'bg-emerald-500')}
              style={{ width: `${pct}%` }}
            />
          </div>
        </div>
      )
    },
  },
  editableColumn('dailyDemand', 'Daily demand', '/day'),
  editableColumn('leadTimeDays', 'Lead time', 'd'),
  editableColumn('safetyStock', 'Safety stock'),
  {
    id: 'reorderPoint',
    header: 'Reorder point',
    accessorFn: (row) => deriveMetrics(row).reorderPoint,
    cell: ({ row }) => {
      const { reorderPoint, daysOfCover } = deriveMetrics(row.original)
      return (
        <div className="tabular-nums">
          <p>{reorderPoint.toLocaleString()}</p>
          <p
            className={cn(
              'text-xs',
              daysOfCover < row.original.leadTimeDays
                ? 'text-destructive'
                : 'text-muted-foreground',
            )}
          >
            {Number.isFinite(daysOfCover) ? `${daysOfCover.toFixed(1)}d cover` : 'no demand'}
          </p>
        </div>
      )
    },
  },
  {
    id: 'reorderQty',
    header: 'Suggested PO',
    accessorFn: (row) => deriveMetrics(row).reorderQty,
    cell: ({ row }) => {
      const { reorderQty } = deriveMetrics(row.original)
      if (reorderQty === 0) return <span className="text-muted-foreground">—</span>
      return (
        <div className="tabular-nums">
          <p className="font-medium">{reorderQty.toLocaleString()}</p>
          <p className="text-xs text-muted-foreground">
            {reorderQty / row.original.casePack} × {row.original.casePack}/case
          </p>
        </div>
      )
    },
    footer: ({ table }) => sumFooter(table, (m) => m.reorderQty),
  },
]

'use client'

import { Wand2 } from 'lucide-react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { Badge } from '#/components/ui/badge'
import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils.ts'
import type { InventoryTableMeta, SkuRow } from './columns'
import { EditableNumberCell } from './editable-cell'
import { deriveMetrics, isExpired } from './formulas'

const formatDate = (iso: string) =>
  new Date(iso).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC',
  })

interface BatchDetailProps {
  row: SkuRow
  meta: InventoryTableMeta
}

export function BatchDetail({ row, meta }: BatchDetailProps) {
  const { allocated, unallocated } = deriveMetrics(row)
  const earliestUsable = [...row.batches]
    .filter((b) => !isExpired(b))
    .sort((a, b) => a.expiresOn.localeCompare(b.expiresOn))[0]?.id

  // The detail cell spans every column of a wide, horizontally scrolling
  // grid — cap the panel's width and pin it left so it stays readable and
  // in view however far the master table is scrolled.
  return (
    <div className="sticky left-4 max-w-2xl space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm text-muted-foreground">
          <span className="font-medium text-foreground">{row.orderedQty.toLocaleString()}</span>{' '}
          units on open orders ·{' '}
          <span className="font-medium text-foreground">{allocated.toLocaleString()}</span>{' '}
          allocated
          {unallocated > 0 ? (
            <>
              {' '}
              ·{' '}
              <span className="font-medium text-amber-700 dark:text-amber-400">
                {unallocated.toLocaleString()} still open
              </span>
            </>
          ) : null}
        </p>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => meta.autoAllocate(row.sku)}
        >
          <Wand2 className="size-3.5" />
          Auto-allocate (FEFO)
        </Button>
      </div>

      <div className="overflow-hidden rounded-md border bg-background">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Lot</TableHead>
              <TableHead>Location</TableHead>
              <TableHead>Expires</TableHead>
              <TableHead className="text-right">On hand</TableHead>
              <TableHead>Allocated</TableHead>
              <TableHead className="text-right">Free</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {row.batches.map((batch) => {
              const expired = isExpired(batch)
              // Everything allocated to this SKU except this batch — the
              // ceiling for a new value here is whatever's left of orderedQty.
              const allocatedElsewhere = allocated - batch.allocated
              return (
                <TableRow key={batch.id} className={cn(expired && 'text-muted-foreground')}>
                  <TableCell className="font-mono text-xs">{batch.lot}</TableCell>
                  <TableCell>{batch.location}</TableCell>
                  <TableCell>
                    <span className="flex items-center gap-2 whitespace-nowrap">
                      {formatDate(batch.expiresOn)}
                      {expired ? (
                        <Badge variant="outline" className="border-transparent bg-destructive/15 text-destructive dark:text-red-300">
                          Expired
                        </Badge>
                      ) : batch.id === earliestUsable ? (
                        <Badge variant="outline">Pick first</Badge>
                      ) : null}
                    </span>
                  </TableCell>
                  <TableCell className="text-right tabular-nums">
                    {batch.onHand.toLocaleString()}
                  </TableCell>
                  <TableCell>
                    <EditableNumberCell
                      label={`Allocated from lot ${batch.lot}`}
                      value={batch.allocated}
                      disabled={expired}
                      validate={(n) => {
                        if (n > batch.onHand) return `Only ${batch.onHand} on hand`
                        if (allocatedElsewhere + n > row.orderedQty) {
                          return `Max ${row.orderedQty - allocatedElsewhere} — order is ${row.orderedQty}`
                        }
                        return null
                      }}
                      onCommit={(n) => meta.updateBatch(row.sku, batch.id, n)}
                    />
                  </TableCell>
                  <TableCell className="text-right tabular-nums">
                    {expired ? '—' : (batch.onHand - batch.allocated).toLocaleString()}
                  </TableCell>
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

'use client'

import { Fragment, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { ExpandedState, SortingState } from '@tanstack/react-table'
import { ArrowDown, ArrowUp, ArrowUpDown } from 'lucide-react'

import {
  Table,
  TableBody,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import type { InventoryTableMeta, SkuRow } from './columns'
import { columns, getMeta } from './columns'
import { BatchDetail } from './batch-detail'

interface InventoryTableProps {
  data: SkuRow[]
  meta: InventoryTableMeta
}

export function InventoryTable({ data, meta }: InventoryTableProps) {
  const [sorting, setSorting] = useState<SortingState>([{ id: 'status', desc: false }])
  const [expanded, setExpanded] = useState<ExpandedState>({ 'SKU-1042': true })

  const table = useReactTable({
    data,
    columns,
    meta,
    state: { sorting, expanded },
    onSortingChange: setSorting,
    onExpandedChange: setExpanded,
    // Rows are keyed by SKU, not array index, so expansion follows the SKU
    // when a formula-backed sort (e.g. Status) moves it after an edit.
    getRowId: (row) => row.sku,
    // Batches aren't subRows of the same shape — the detail panel is custom
    // markup — so every row can expand without a getSubRows.
    getRowCanExpand: () => true,
    // Every edit produces a new `data` array; without this, TanStack would
    // collapse all rows each time a cell is saved.
    autoResetExpanded: false,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
  })

  const columnCount = table.getVisibleLeafColumns().length

  return (
    <div className="overflow-hidden rounded-md border">
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => {
                const canSort = header.column.getCanSort()
                const sorted = header.column.getIsSorted()
                return (
                  <TableHead
                    key={header.id}
                    aria-sort={
                      sorted === 'asc' ? 'ascending' : sorted === 'desc' ? 'descending' : undefined
                    }
                    className="whitespace-nowrap"
                  >
                    {header.isPlaceholder ? null : canSort ? (
                      <button
                        type="button"
                        onClick={header.column.getToggleSortingHandler()}
                        className="flex items-center gap-2"
                      >
                        {flexRender(header.column.columnDef.header, header.getContext())}
                        {sorted === 'asc' ? (
                          <ArrowUp className="size-3" />
                        ) : sorted === 'desc' ? (
                          <ArrowDown className="size-3" />
                        ) : (
                          <ArrowUpDown className="size-3 opacity-50" />
                        )}
                      </button>
                    ) : (
                      flexRender(header.column.columnDef.header, header.getContext())
                    )}
                  </TableHead>
                )
              })}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.length ? (
            table.getRowModel().rows.map((row) => (
              <Fragment key={row.id}>
                <TableRow data-state={row.getIsExpanded() ? 'selected' : undefined}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
                {row.getIsExpanded() ? (
                  <TableRow className="hover:bg-transparent">
                    <TableCell colSpan={columnCount} className="bg-muted/30 p-4">
                      <BatchDetail row={row.original} meta={getMeta(table)} />
                    </TableCell>
                  </TableRow>
                ) : null}
              </Fragment>
            ))
          ) : (
            <TableRow>
              <TableCell colSpan={columnCount} className="h-24 text-center">
                No results.
              </TableCell>
            </TableRow>
          )}
        </TableBody>
        <TableFooter>
          {table.getFooterGroups().map((footerGroup) => (
            <TableRow key={footerGroup.id}>
              {footerGroup.headers.map((header) => (
                <TableCell key={header.id} className="font-medium">
                  {flexRender(header.column.columnDef.footer, header.getContext())}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableFooter>
      </Table>
    </div>
  )
}

